import java.io.*;
import java.util.*;

public class Main {
    static class RunCounter {
        int previous;
        int runLength;
        int answer;
        boolean started;

        void add(int c) {
            if (!started) {
                previous = c;
                runLength = 1;
                started = true;
            } else if (c == previous) {
                runLength++;
            } else {
                if ((runLength & 1) == 0)
                    answer++;
                previous = c;
                runLength = 1;
            }
        }

        int result() {
            if (started && (runLength & 1) == 0)
                answer++;
            return answer;
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        String s = in.next();
        RunCounter counter = s.chars().collect(RunCounter::new, RunCounter::add, (a, b) -> {});
        out.printLine(counter.result());
        out.close();
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c))
                res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

class OutputWriter {
    private PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void printLine(int i) {
        writer.println(i);
    }

    public void close() {
        writer.close();
    }
}
